#!/usr/bin/env python3
import sys
from collections import Counter

import h5py
import numpy as np
from scipy import sparse


TARGETS = ["PABPC1", "NUDT21", "LEO1"]


def decode(values):
    arr = np.asarray(values)
    if arr.dtype.kind in "SO":
        return np.asarray([
            x.decode("utf-8") if isinstance(x, (bytes, np.bytes_)) else str(x)
            for x in arr
        ], dtype=object)
    return arr.astype(str)


def read_column(group, name):
    obj = group[name]
    if isinstance(obj, h5py.Dataset):
        return decode(obj[:])
    encoding = obj.attrs.get("encoding-type", "")
    if isinstance(encoding, bytes):
        encoding = encoding.decode("utf-8")
    if encoding == "categorical" or ("codes" in obj and "categories" in obj):
        codes = np.asarray(obj["codes"][:], dtype=int)
        categories = decode(obj["categories"][:])
        return np.asarray([categories[c] if c >= 0 else "" for c in codes], dtype=object)
    raise ValueError(f"Unsupported column encoding for {name}: {encoding}")


def read_index(group):
    key = group.attrs.get("_index", "_index")
    if isinstance(key, bytes):
        key = key.decode("utf-8")

